package com.igviewer.archive.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Extensionless media (Instagram sometimes names files with a bare timestamp) must still
 * be classified by content, or the media is dropped to a non-previewable chip.
 * Uses only generated bytes, never real data.
 */
class MediaResolverSniffTest {

    private fun tempWith(bytes: IntArray): File {
        val f = File.createTempFile("sniff", ".bin")
        f.deleteOnExit()
        f.writeBytes(ByteArray(bytes.size) { bytes[it].toByte() })
        return f
    }

    private fun jpeg() = tempWith(intArrayOf(0xFF, 0xD8, 0xFF, 0xE0, 0, 0, 0, 0, 0, 0, 0, 0))
    private fun png() = tempWith(intArrayOf(0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A))
    private fun gif() = tempWith("GIF89a....".map { it.code }.toIntArray())
    private fun webp() = tempWith("RIFFxxxxWEBP".map { it.code }.toIntArray())
    private fun heic() = tempWith("xxxxftypheic".map { it.code }.toIntArray())
    private fun mp4() = tempWith("xxxxftypisom".map { it.code }.toIntArray())

    @Test
    fun detects_common_images() {
        assertEquals("image/jpeg", MediaResolver.sniffMime(jpeg()))
        assertEquals("image/png", MediaResolver.sniffMime(png()))
        assertEquals("image/gif", MediaResolver.sniffMime(gif()))
        assertEquals("image/webp", MediaResolver.sniffMime(webp()))
        assertEquals("image/heic", MediaResolver.sniffMime(heic()))
    }

    @Test
    fun detects_video_containers() {
        assertEquals("video/mp4", MediaResolver.sniffMime(mp4()))
        assertTrue(MediaResolver.sniffMime(mp4())!!.startsWith("video/"))
    }

    @Test
    fun returns_null_for_unknown_content() {
        assertNull(MediaResolver.sniffMime(tempWith("hello world, not media".map { it.code }.toIntArray())))
    }
}
